&lt;span id=&#34;cb4-157&#34;&gt;&lt;a href=&#34;#cb4-157&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;        &lt;span class=&#34;op&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb4-158&#34;&gt;&lt;a href=&#34;#cb4-158&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    &lt;span class=&#34;op&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;
